select *
from Tblmi_cont_mst


        and seq = #{seq}


        and ch_tp = #{ch_tp}


        and orig_id = #{orig_id}


        and inta_key = #{inta_key}


Limit 1

select a.seq , a.CONT_TP , a.CONT_SUB , a.CONT_TOP_BODY , a.CONT_BODY , a.FROM_TO , a.SEND_TP , b.list_val as send_to , b.list_nm AS send_nm , a.THM_URL , a.BR_YN , a.SUP_YN , a.MSG_TP , a.KKO_IMG_CD , a.KKO_IMG_URL , a.KKO_BTN_NM , a.KKO_BTN_URL , a.KKO_MSG_TP , a.KKO_BTN_OBJ , a.KKO_PRICE , a.KKO_CURRENCY_TYPE , a.KKO_TITLE , a.KKO_HEADER , a.COUPON_SEQ , a.SHORT_URL_YN , a.IMG_CD_1 , a.IMG_CD_2 , a.IMG_CD_3 , a.IMG_CD_4 , a.IMG_CD_5 , a.IMG_CD_6 , a.RCS_BTN_INS_TP , a.RCS_BTN_CNT , a.RCS_BTN_OBJ , a.RCS_BTN_1 , a.RCS_BTN_TP_1 , a.RCS_BTN_CONT_1 , a.RCS_BTN_2 , a.RCS_BTN_TP_2 , a.RCS_BTN_CONT_2 , a.RCS_BTN_3 , a.RCS_BTN_TP_3 , a.RCS_BTN_CONT_3 , a.RCS_FOOTER , a.KEY_ID , a.CONT_GRP_CD , #{reg_id} as reg_id from Tblmi_cont_lst as a INNER JOIN tblmi_set_lst AS b ON a.SEND_TO = b.SEQ
and a.SEQ = #{seq}
and a.CONT_CD = #{cont_cd}
and a.CONT_TP = #{cont_tp}
and a.CONT_GRP_CD = #{cont_grp_cd}
and a.USE_YN = #{use_yn}

