insert into tblmicp_cont_mst (
    cont_seq
    , ch_tp
    , cont_nm
    , camp_nm
    , team_cd
    , usr_key
    , sales_nm
    , avo_nm
    , avo_id
    , inten_id
    , orig_id
    , inta_key
    , inta_ve
    , pub_yn
    , cont_grp_cd
    , reg_id
    , upd_id
)
values (
    #{cont_seq}
    , #{ch_tp}
    , #{cont_nm}
    , #{camp_nm}
    , #{team_cd}
    , #{usr_key}
    , #{sales_nm}
    , #{avo_nm}
    , #{avo_id}
    , #{inten_id}
    , #{orig_id}
    , #{inta_key}
    , #{inta_ve}
    , #{pub_yn}
    , #{cont_grp_cd}
    , #{reg_id}
    , #{upd_id}
)

mapper.update:

    SELECT seq
        , cont_grp_cd
    FROM tblmicp_cont_mst
    WHERE inten_id = #{inten_id}
        and orig_id = #{orig_id}
        and inta_key = #{inta_key}
        and avo_id = #{avo_id}

update tblmicp_cont_mst set
    pub_yn = #{pub_yn}

        , cont_seq = #{cont_seq}


        , cont_nm = #{cont_nm}


        , sales_nm = #{sales_nm}


        , avo_nm = #{avo_nm}


        , inta_ve = #{inta_ve}


        , pub_yn = #{pub_yn}


        , upd_id = #{upd_id}


    inten_id = #{inten_id}
    and orig_id = #{orig_id}
    and inta_key = #{inta_key}
    and inta_ve = #{inta_ve}
    and avo_id = #{avo_id}

update tblmi_cont_mst
set avo_id   = #{avo_id}
  , inten_id = #{inten_id}
  , orig_id  = #{orig_id}
where seq in (
    select seq
    from (
        (
            select *
            from tblmi_cont_mst
            where (INTEN_ID is null or INTEN_ID = '')
                and (ORIG_ID is null or ORIG_ID = '')
                and INTA_KEY = #{inta_key}
                and INTA_VE = #{inta_ve}
                order by seq asc
            limit 1
        ) as tmp
    )
)

update tblmicp_cont_mst set
    pub_yn = #{pub_yn}

        , cont_seq = #{cont_seq}


        , cont_nm = #{cont_nm}


        , sales_nm = #{sales_nm}


        , avo_nm = #{avo_nm}


        , inta_ve = #{inta_ve}


        , pub_yn = #{pub_yn}


        , upd_id = #{upd_id}


        inten_id = #{inten_id}
        and orig_id = #{orig_id}
        and inta_key = #{inta_key}
        and inta_ve = #{inta_ve}


    SELECT pro_id
    FROM Tblmicp_program
    WHERE inten_id = #{inten_id}
        and orig_id = #{orig_id}
        and inta_key = #{inta_key}
        and inta_ve = #{inta_ve}

update Tblmicp_program set
    PRO_ST = #{pro_st}
    , MAX_START_DT = current_timestamp

    inten_id = #{inten_id}
        and orig_id = #{orig_id}
        and inta_key = #{inta_key}
        and inta_ve = #{inta_ve}

update tblmicp_campaign
set pro_id = #{pro_id}

    , camp_st = #{camp_st}


    , tar_cnt = #{tar_cnt}


    , start_dt = #{start_dt}


    pro_id = #{pro_id}

        and seq = #{seq}
